describe('#live()', function () {

    it('SGD as source against USD + THB', function (done) {

        this.timeout(10000);

        var source = 'SGD';
        var currencies = ['USD', 'THB'];

        var liveQuery = {
            source: source,
            currencies: currencies.join(',')
        };

        var live = api.live;
        live(liveQuery)
            .then(function (result) {

                result = _.get(result, live.CONTENT_EXPR);

                assert.equal(2, _.keys(result).length);

                _.each(currencies, function (currency) {
                    var propertyName = source + currency;
                    expect(result).to.have.property(propertyName);
                });

                return done();
            })
            .catch(function (err) {
                return done(err);
            });
    });
});

'use strict';

var _ = require('lodash');
var utils = require('./lib/utils');

/**
 * A module for interacting with currency-conversion API
 * @module currency-conversion
 */

/**
 * currency-conversion constructor.
 * @param {object} options Options to be passed in
 * @constructor
 */
function API(options) {

    this.options = utils.extend(
        {},
        options,
        {
            host: 'apilayer.net',
            context: 'api',
            key_type: 'access_key',
            secure: false,
            followRedirect: false
        }
    );

    /**
     * Load the apis from apis directory
     * This file holds all version information
     * @private
     */
    var apis = require('./api');
    this.addAPIs(apis);
}

/**
 * Add API endpoints to object
 *
 * @param {Array} api Api to be added
 * @private
 */
API.prototype.addAPIs = function (apis) {

    for (var apiName in apis) {

        var API = apis[apiName];
        var api = API.bind(this);
        _.extend(api, API);

        this[apiName] = api;
    }
};

/**
 * Exports currency-conversion.
 */
module.exports = API;

